package capability

type Settings struct{ManualSeeds bool `json:"manual_seeds"`;CSVImport bool `json:"csv_import"`;SearchProvider bool `json:"search_provider"`;Sitemap bool `json:"sitemap"`;Robots bool `json:"robots"`;LinkDiscovery bool `json:"link_discovery"`;SubdomainFromCrawl bool `json:"subdomain_from_crawl"`;ActiveProbe bool `json:"active_probe"`;DeepCrawl bool `json:"deep_crawl"`;ExternalLinks bool `json:"external_links"`;WordPress bool `json:"wordpress"`;WooCommerce bool `json:"woocommerce"`;Phone bool `json:"phone"`;Email bool `json:"email"`;Business bool `json:"business"`;Social bool `json:"social"`;PageClassification bool `json:"page_classification"`;BrowserRender bool `json:"browser_render"`}
func Defaults()Settings{return Settings{ManualSeeds:true,CSVImport:true,SearchProvider:true,Sitemap:true,Robots:true,LinkDiscovery:true,SubdomainFromCrawl:true,ActiveProbe:true,DeepCrawl:true,WordPress:true,WooCommerce:true,Phone:true,Email:true,Business:true,Social:true,PageClassification:true}}
func (s Settings)Map()map[string]bool{return map[string]bool{"manual_seeds":s.ManualSeeds,"csv_import":s.CSVImport,"search_provider":s.SearchProvider,"sitemap":s.Sitemap,"robots":s.Robots,"link_discovery":s.LinkDiscovery,"subdomain_from_crawl":s.SubdomainFromCrawl,"active_probe":s.ActiveProbe,"deep_crawl":s.DeepCrawl,"external_links":s.ExternalLinks,"wordpress":s.WordPress,"woocommerce":s.WooCommerce,"phone":s.Phone,"email":s.Email,"business":s.Business,"social":s.Social,"page_classification":s.PageClassification,"browser_render":s.BrowserRender}}
